-- =====================================================================
-- Saberes que Cultivam — SIMULAÇÃO: povoa o banco com dados FICTÍCIOS (o projeto inteiro, comprimido até 15/10/2026)
-- ATENÇÃO, leia antes de rodar:
--   * O SEAB/MDA e toda a equipe passam a ver estes números como se fossem do projeto (metas, unidades acompanhadas,
--     capacitações, despesas). Use num banco de teste ou só enquanto ninguém de fora estiver olhando, e rode o limpar.sql depois.
--   * Recusa rodar se o banco já tiver registro REAL de campo (unidade produtiva, lote, distribuição ou visita): não mistura dado real com fictício.
--   * Não cria acesso (login) para ninguém e não mexe nas biofábricas reais: cria três biofábricas simuladas (SRN, SCE, SAP).
--   * Despesas: o desembolso inteiro do plano (R$ 400.000,00) como pago; com só a 1ª parcela recebida, o painel avisa "acima do recebido".
--   * 798 registros: 3 unidades, 12 itens, 8 membros, 42 lotes, 32 agricultores, 139 distribuicoes, 137 visitas, 22 eventos, 259 presencas, 14 entregas, 130 despesas.
--   * Para desfazer: supabase/simulacao/limpar.sql (apaga só o que tem id ffffffff-0000-4000-8000-…).
-- Rode inteiro, de uma vez, no SQL Editor do Supabase. Se der erro, nada é gravado (tudo numa transação).
-- GERADO por ferramentas/simulacao_sql.js (2026-10-15). Não edite à mão: gere de novo.
-- =====================================================================
begin;
do $$ begin
  if exists (select 1 from public.unidades where id::text like 'ffffffff-0000-4000-8000-%') then
    raise exception 'A simulação já está no banco. Rode o limpar.sql antes de povoar de novo.';
  end if;
  if exists (select 1 from public.agricultores where id::text not like 'ffffffff-0000-4000-8000-%') or exists (select 1 from public.lotes where id::text not like 'ffffffff-0000-4000-8000-%')
     or exists (select 1 from public.distribuicoes where id::text not like 'ffffffff-0000-4000-8000-%') or exists (select 1 from public.visitas where id::text not like 'ffffffff-0000-4000-8000-%') then
    raise exception 'O banco já tem registros reais de campo (unidades produtivas, lotes, distribuições ou visitas). A simulação não mistura dado real com fictício: use um banco de teste.';
  end if;
end $$;

-- unidades (3)

-- itens (12)

-- membros (8)

-- lotes (42)

-- agricultores (32)

-- distribuicoes (139)

-- visitas (137)

-- eventos (22)

-- presencas (259)

-- entregas (14)

-- despesas (130)

commit;

select (select count(*) from public.unidades where id::text like 'ffffffff-0000-4000-8000-%') as unidades,
       (select count(*) from public.itens where id::text like 'ffffffff-0000-4000-8000-%') as itens,
       (select count(*) from public.membros where id::text like 'ffffffff-0000-4000-8000-%') as membros,
       (select count(*) from public.lotes where id::text like 'ffffffff-0000-4000-8000-%') as lotes,
       (select count(*) from public.agricultores where id::text like 'ffffffff-0000-4000-8000-%') as agricultores,
       (select count(*) from public.distribuicoes where id::text like 'ffffffff-0000-4000-8000-%') as distribuicoes,
       (select count(*) from public.visitas where id::text like 'ffffffff-0000-4000-8000-%') as visitas,
       (select count(*) from public.eventos where id::text like 'ffffffff-0000-4000-8000-%') as eventos,
       (select count(*) from public.presencas where id::text like 'ffffffff-0000-4000-8000-%') as presencas,
       (select count(*) from public.entregas where id::text like 'ffffffff-0000-4000-8000-%') as entregas,
       (select count(*) from public.despesas where id::text like 'ffffffff-0000-4000-8000-%') as despesas;
